using IndexPair = std::pair<std::ptrdiff_t, std::ptrdiff_t>;

[[nodiscard]] std::optional<IndexPair> two_sum(std::span<const int> nums, int target) {
  std::unordered_map<std::int64_t, std::ptrdiff_t> seen;  // value -> first index where it was seen
  for (std::ptrdiff_t i = 0; i < std::ssize(nums); ++i) {
    const std::int64_t complement = std::int64_t{target} - nums[i];  // can't overflow in 64 bits
    if (const auto it = seen.find(complement); it != seen.end()) return IndexPair{it->second, i};
    seen.try_emplace(nums[i], i);
  }
  return std::nullopt;
}

[[nodiscard]] std::string show(const std::optional<IndexPair>& pair) {
  return pair ? std::format("{{{}, {}}}", pair->first, pair->second) : "no value";
}

int main() {
  const std::vector<int> a{2, 7, 11, 15};
  const std::vector<int> b{3, 3};
  const std::vector<int> c{1, 2};
  std::cout << show(two_sum(a, 9)) << ' ' << show(two_sum(b, 6)) << ' ' << show(two_sum(c, 7)) << '\n';
}

