[[nodiscard]] std::optional<int> most_frequent(std::span<const int> ids) {
  std::unordered_map<int, std::int64_t> counts;
  for (const int id : ids) ++counts[id];
  if (counts.empty()) return std::nullopt;
  // Worse means less frequent, or as frequent with a larger id; the maximum is the answer.
  const auto worse = [](const auto& a, const auto& b) {
    return a.second < b.second || (a.second == b.second && a.first > b.first);
  };
  return std::ranges::max_element(counts, worse)->first;
}

int main() {
  for (const std::vector<int>& ids : {std::vector<int>{4, 1, 4, 2, 1}, std::vector<int>{7}, std::vector<int>{}}) {
    const std::optional<int> best = most_frequent(ids);
    std::cout << (best ? std::to_string(*best) : "no value") << '\n';
  }
}

