[[nodiscard]] std::optional<std::ptrdiff_t> first_unique(std::string_view s) {
  std::array<std::int64_t, 256> counts{};
  const auto slot = [](char c) { return static_cast<unsigned char>(c); };  // char may be negative
  for (const char c : s) ++counts[slot(c)];
  const auto it = std::ranges::find_if(s, [&](char c) { return counts[slot(c)] == 1; });
  if (it == s.end()) return std::nullopt;
  return it - s.begin();
}

int main() {
  for (const std::string_view s : {"leetcode", "loveleetcode", "aabb"}) {
    const std::optional<std::ptrdiff_t> index = first_unique(s);
    std::cout << s << ": " << (index ? std::to_string(*index) : "no value") << '\n';
  }
}

