[[nodiscard]] std::vector<std::vector<std::string>> group_anagrams(std::span<const std::string> words) {
  std::unordered_map<std::string, std::vector<std::string>> groups;
  for (const std::string& word : words) {
    std::string key = word;
    std::ranges::sort(key);
    groups[key].push_back(word);
  }
  std::vector<std::vector<std::string>> out;
  for (auto& group : groups | std::views::values) out.push_back(std::move(group));
  std::ranges::sort(out);  // the map's order is unspecified; sort for a stable result
  return out;
}

int main() {
  const std::vector<std::string> words{"eat", "tea", "tan", "ate", "nat", "bat"};
  for (const auto& group : group_anagrams(words)) {
    std::string_view separator;
    for (const std::string& word : group) {
      std::cout << separator << word;
      separator = " ";
    }
    std::cout << '\n';
  }
}

