struct Cell {
  std::int32_t x;
  std::int32_t y;
};

struct CellHash {
  std::size_t operator()(const Cell& c) const noexcept {
    const std::uint64_t high = static_cast<std::uint32_t>(c.x);
    const std::uint64_t low = static_cast<std::uint32_t>(c.y);
    return std::hash<std::uint64_t>{}((high << 32) | low);
  }
};

int main() {
  std::unordered_map<Cell, int, CellHash> visits;
  visits[{1, 2}] = 1;
}
